import numpy as np

def step(lam,y,s):
    # stable reorthogonalized Arnoldi orthogonal polynomial
    vs=[y/np.linalg.norm(y)]
    for j in range(s):
        v=lam*vs[-1]
        for z in vs:
            v-=np.dot(z,v)*z
        for z in vs:
            v-=np.dot(z,v)*z
        nv=np.linalg.norm(v)
        if nv<1e-15: return None
        vs.append(v/nv)
    return vs[-1]*(-1)**s

